  1862→    if (!target) return;
  1863→    const exact  = el.dataset.exact === '1';
  1864→    const suffix = (!exact && target > 0) ? '+' : '';
  1865→    const duration = 1600;
  1866→    const step = target / (duration / 16);
  1867→    let current = 0;
  1868→    const timer = setInterval(() => {
  1869→        current = Math.min(current + step, target);
  1870→        el.textContent = Math.floor(current) + suffix;
  1871→        if (current >= target) clearInterval(timer);
  1872→    }, 16);
  1873→}
  1874→const countObs = new IntersectionObserver((entries) => {
  1875→    entries.forEach(e => {
  1876→        if (e.isIntersecting) { countUp(e.target); countObs.unobserve(e.target); }
  1877→    });
  1878→}, { threshold: 0.5 });
  1879→document.querySelectorAll('.count-up[data-target]').forEach(el => countObs.observe(el));
