  1897→function initMobileCarousel(gridId, dotsId) {
  1898→    const grid   = document.getElementById(gridId);
  1899→    const dotsEl = document.getElementById(dotsId);
  1900→    if (!grid || !dotsEl) return;
  1901→    const mq = window.matchMedia('(max-width:640px)');
  1902→    function buildDots() {
  1903→        dotsEl.innerHTML = '';
  1904→        if (!mq.matches) return;
  1905→        const cards = Array.from(grid.children);
  1906→        cards.forEach((_, i) => {
  1907→            const btn = document.createElement('button');
  1908→            btn.className = 'mcd' + (i === 0 ? ' active' : '');
  1909→            btn.setAttribute('aria-label', 'Slide ' + (i + 1));
  1910→            btn.addEventListener('click', () => {
  1911→                const pl = parseFloat(getComputedStyle(grid).paddingLeft) || 0;
  1912→                grid.scrollTo({ left: Math.max(0, cards[i].offsetLeft - pl), behavior: 'smooth' });
  1913→            });
  1914→            dotsEl.appendChild(btn);
  1915→        });
  1916→    }
  1917→    function updateDots() {
  1918→        if (!mq.matches) return;
  1919→        const cards = Array.from(grid.children);
  1920→        const gap   = parseFloat(getComputedStyle(grid).gap) || 16;
  1921→        const cardW = (cards[0]?.offsetWidth || 1) + gap;
  1922→        const idx   = Math.min(Math.round(grid.scrollLeft / cardW), cards.length - 1);
  1923→        dotsEl.querySelectorAll('.mcd').forEach((d, i) => d.classList.toggle('active', i === idx));
  1924→    }
  1925→    grid.addEventListener('scroll', updateDots, { passive: true });
  1926→    mq.addEventListener('change', buildDots);
  1927→    buildDots();
  1928→}
