  1941→(function() {
  1942→    const row   = document.getElementById('galeriRow');
  1943→    const prev  = document.getElementById('galeriPrev');
  1944→    const next  = document.getElementById('galeriNext');
  1945→    if (!row || !prev || !next) return;
  1946→    const items = Array.from(row.children);
  1947→    const total = items.length;
  1948→    const vis   = () => window.innerWidth < 600 ? 2 : window.innerWidth < 900 ? 2 : 4;
  1949→    let offset  = 0;
  1950→    function clamp(v) { return Math.max(0, Math.min(v, total - vis())); }
  1951→    function render() {
  1952→        items.forEach((el, i) => {
  1953→            el.style.display = (i >= offset && i < offset + vis()) ? '' : 'none';
  1954→        });
  1955→        prev.disabled = offset === 0;
  1956→        next.disabled = offset >= total - vis();
  1957→        prev.style.opacity = prev.disabled ? '.4' : '';
  1958→        next.style.opacity = next.disabled ? '.4' : '';
  1959→    }
  1960→    prev.addEventListener('click', () => { offset = clamp(offset - 1); render(); });
  1961→    next.addEventListener('click', () => { offset = clamp(offset + 1); render(); });
  1962→    window.addEventListener('resize', () => { offset = clamp(offset); render(); });
  1963→    render();
