  2008→        if (rafId) cancelAnimationFrame(rafId);
  2009→        rafId = requestAnimationFrame(() => {
  2010→            const rect = hero.getBoundingClientRect();
  2011→            const cx   = (e.clientX - rect.left) / rect.width  - 0.5;
  2012→            const cy   = (e.clientY - rect.top)  / rect.height - 0.5;
  2013→            fc1.style.transform = `translate(${cx * -16}px, ${cy * -11}px) rotate(-1deg)`;
